from django.contrib.sitemaps import Sitemap
from .models import CustomerIncidentPostmortem

class SupportIncidentSitemap(Sitemap):
    changefreq = 'weekly'
    priority = 0.4

    def items(self):
        # Restrict items exclusively to incidents explicitly marked for public transparency
        return CustomerIncidentPostmortem.objects.filter(status='RESOLVED', is_public_disclosure=True)

    def location(self, item):
        return f"/support/incidents/{item.incident_number}/summary/"
